const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const china = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', 'China'));

  const year2000 = ee.DateRange('2000-01-01', '2000-12-31');
  const year2017 = ee.DateRange('2017-01-01', '2017-12-31');

  // 2. Data Acquisition - MODIS Vegetation Index
  function getYearlyNDVI(yearRange) {
    const collection = ee.ImageCollection('MODIS/006/MOD13Q1')
      .filterBounds(china)
      .filterDate(yearRange)
      .select('NDVI');

    if (collection.size().getInfo() === 0) {
      return null;
    }

    // Calculate annual mean NDVI
    const meanImg = collection.mean().multiply(0.0001); // Scale factor
    return meanImg;
  }

  // Get NDVI for both years
  const ndvi2000 = getYearlyNDVI(year2000);
  const ndvi2017 = getYearlyNDVI(year2017);

  // Check for empty collections
  if (!ndvi2000 || !ndvi2017) {
    console.log("2000 Images: 0");
    console.log("2017 Images: 0");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean NDVI over China
  const reducer = ee.Reducer.mean();

  const stats2000 = ndvi2000.reduceRegion({
    reducer: reducer,
    geometry: china,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2017 = ndvi2017.reduceRegion({
    reducer: reducer,
    geometry: china,
    scale: 1000,
    maxPixels: 1e9
  });

  const mean2000 = stats2000.get('NDVI').getInfo();
  const mean2017 = stats2017.get('NDVI').getInfo();

  // Check for no valid pixels
  if (mean2000 === null || mean2017 === null) {
    console.log("No valid pixels in one or both years");
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (mean2000 === undefined || mean2017 === undefined || 
      isNaN(mean2000) || isNaN(mean2017) ||
      mean2000 > 1 || mean2000 < -1 || 
      mean2017 > 1 || mean2017 < -1) {
    console.log("Calculation failure - invalid NDVI values");
    console.log("<answer>C3</answer>");
    return;
  }

  // 4. Output results and final answer
  console.log(`2000 Mean NDVI: ${mean2000.toFixed(4)}`);
  console.log(`2017 Mean NDVI: ${mean2017.toFixed(4)}`);
  console.log(`Change: ${(mean2017 - mean2000).toFixed(4)}`);

  // Determine answer based on NDVI increase
  if (mean2017 > mean2000) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
